import React from 'react';
import Box from '@mui/material/Box';
import Login from './Login';
import { Fade, Typography } from '@mui/material';
import StorefrontOutlinedIcon from '@mui/icons-material/StorefrontOutlined';
import PointOfSaleOutlinedIcon from '@mui/icons-material/PointOfSaleOutlined';
import InventoryOutlinedIcon from '@mui/icons-material/InventoryOutlined';
import BarChartOutlinedIcon from '@mui/icons-material/BarChartOutlined';

const FEATURES = [
  { icon: <PointOfSaleOutlinedIcon sx={{ fontSize: 17 }} />, label: 'Sales & Checkout', desc: 'Fast billing with multiple payment modes' },
  { icon: <StorefrontOutlinedIcon sx={{ fontSize: 17 }} />, label: 'Multi-outlet', desc: 'Manage multiple branches from one place' },
  { icon: <InventoryOutlinedIcon sx={{ fontSize: 17 }} />, label: 'Inventory', desc: 'Real-time stock tracking and alerts' },
  { icon: <BarChartOutlinedIcon sx={{ fontSize: 17 }} />, label: 'Analytics', desc: 'Sales reports and profit insights' },
];

const Auth = () => {
  return (
    <Box
      data-testid="Terms and condition Page"
      sx={{ height: '100vh', display: 'flex', overflow: 'hidden' }}
    >
      {/* ══════════════════ LEFT PANEL ══════════════════ */}
      <Box
        sx={{
          display: { xs: 'none', md: 'flex' },
          flex: '0 0 58%',
          flexDirection: 'column',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {/* Background image */}
        <Box
          sx={{
            position: 'absolute',
            inset: 0,
            backgroundImage: 'url(/images/posBack3.png)',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundRepeat: 'no-repeat',
            opacity: 0.86,
          }}
        />

        {/* Gradient overlay — stronger on the left, lighter on the right so the image stays visible */}
        <Box
          sx={{
            position: 'absolute',
            inset: 0,
            background:
              'linear-gradient(100deg, rgba(10,20,60,0.72) 0%, rgba(10,20,60,0.56) 34%, rgba(10,20,60,0.26) 66%, rgba(10,20,60,0.12) 100%)',
          }}
        />

        {/* Content */}
        <Box
          sx={{
            position: 'relative',
            zIndex: 1,
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            px: { md: 5, lg: 7 },
            pt: { md: 4, lg: 5 },
            pb: { md: 4, lg: 5 },
            alignItems: 'flex-start',
          }}
        >
          {/* Spacer */}
          <Box sx={{ flex: 1 }} />

          <Box
            sx={{
              width: '100%',
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            {/* Headline */}
            <Fade in timeout={600}>
              <Box sx={{ mb: { md: 1.5, lg: 1.75 }, maxWidth: { md: 760, lg: 860 } }}>
                <Typography
                  sx={{
                    fontSize: { md: '1.7rem', lg: '2.15rem', xl: '2.4rem' },
                    fontWeight: 800,
                    color: '#fff',
                    lineHeight: 1.12,
                    letterSpacing: '-0.03em',
                    textShadow: '0 2px 18px rgba(0,0,0,0.38)',
                    mb: 1,
                    whiteSpace: 'nowrap',
                  }}
                >
                  Smarter Sales.{' '}
                  <Box component="span" sx={{ color: '#93C5FD' }}>
                    Faster Growth.
                  </Box>
                </Typography>
                <Typography
                  sx={{
                    fontSize: { md: '0.84rem', lg: '0.92rem' },
                    color: 'rgba(255,255,255,0.76)',
                    lineHeight: 1.6,
                    whiteSpace: 'nowrap',
                  }}
                >
                  Your all-in-one POS platform — manage sales, inventory and analytics from one powerful dashboard.
                </Typography>
              </Box>
            </Fade>

            {/* Features list */}
            <Fade in timeout={800}>
              <Box sx={{ width: '100%' }}>
                <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: { md: 0.7, lg: 0.85 } }}>
                  {FEATURES.map(({ icon, label, desc }) => (
                    <Box
                      key={label}
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'flex-start',
                        gap: 0.5,
                        px: { md: 1, lg: 1.1 },
                        py: { md: 0.95, lg: 1.05 },
                        borderRadius: '12px',
                        background: 'rgba(255,255,255,0.08)',
                        border: '1px solid rgba(255,255,255,0.12)',
                        backdropFilter: 'blur(12px)',
                        minWidth: 0,
                      }}
                    >
                      <Box sx={{ minWidth: 0, width: '100%' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.65, minWidth: 0, mb: 0.25 }}>
                          <Box
                            sx={{
                              flexShrink: 0,
                              width: 26,
                              height: 26,
                              borderRadius: '8px',
                              background: 'rgba(147,197,253,0.18)',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              color: '#93C5FD',
                            }}
                          >
                            {icon}
                          </Box>
                          <Typography
                            sx={{
                              fontSize: '0.72rem',
                              fontWeight: 700,
                              color: '#fff',
                              lineHeight: 1.25,
                              whiteSpace: 'nowrap',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              minWidth: 0,
                              flex: 1,
                            }}
                          >
                            {label}
                          </Typography>
                        </Box>
                        <Typography
                          sx={{
                            fontSize: '0.64rem',
                            color: 'rgba(255,255,255,0.66)',
                            lineHeight: 1.35,
                            display: '-webkit-box',
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: 'vertical',
                            overflow: 'hidden',
                          }}
                        >
                          {desc}
                        </Typography>
                      </Box>
                    </Box>
                  ))}
                </Box>
              </Box>
            </Fade>
          </Box>

        </Box>
      </Box>

      {/* ══════════════════ RIGHT PANEL ══════════════════ */}
      <Box
        sx={{
          flex: { xs: 1, md: '0 0 42%' },
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative',
          overflow: 'hidden',
          background: {
            xs: 'linear-gradient(148deg, #0F1D4D 0%, #0d1870 50%, #060c3e 100%)',
            md: '#F8FAFF',
          },
          px: { xs: 3, sm: 5, md: 5, lg: 7 },
          py: { xs: 4, md: 0 },
        }}
      >
        {/* Subtle background blobs — desktop */}
        <Box sx={{ display: { xs: 'none', md: 'block' }, position: 'absolute', top: -120, right: -120, width: 340, height: 340, borderRadius: '50%', background: 'radial-gradient(circle, rgba(37,99,235,0.07) 0%, transparent 70%)', pointerEvents: 'none' }} />
        <Box sx={{ display: { xs: 'none', md: 'block' }, position: 'absolute', bottom: -100, left: -100, width: 300, height: 300, borderRadius: '50%', background: 'radial-gradient(circle, rgba(37,99,235,0.05) 0%, transparent 70%)', pointerEvents: 'none' }} />

        {/* Mobile brand header */}
        <Box
          sx={{
            display: { xs: 'flex', md: 'none' },
            flexDirection: 'column',
            alignItems: 'center',
            gap: 1,
          }}
        >
          <Box component="img" src="/images/logo.png" sx={{ height: 48, width: 'auto', mb: 0.5 }} />
          <Typography sx={{ fontSize: { xs: '1.25rem', sm: '1.5rem' }, fontWeight: 800, color: '#fff', letterSpacing: '-0.02em', textAlign: 'center', lineHeight: 1.2 }}>
            Smarter Sales.<br />
            <Box component="span" sx={{ color: 'rgba(147,197,253,0.9)' }}>Faster Growth.</Box>
          </Typography>
        </Box>

        <Login />
      </Box>
    </Box>
  );
};

export default Auth;
