import React, { CSSProperties } from 'react';
import {
  Box,
  Table as MuiTable,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
  Checkbox,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { Row, RowData, Table, flexRender } from '@tanstack/react-table';
import SkeletonTable from './SkeletonTable';
import InboxOutlinedIcon from '@mui/icons-material/InboxOutlined';

declare module '@tanstack/react-table' {
  interface TableMeta<TData extends RowData> {
    getRowStyles: (row: Row<TData>) => CSSProperties;
  }
}

type ReactTableProps<TData> = {
  isLoading: boolean;
  onRowClick?: (row: TData) => void;
} & Table<TData>;

const ReactTable = <TData extends object>({
  isLoading,
  onRowClick,
  ...tableData
}: ReactTableProps<TData>) => {
  const columnsLength = tableData.getVisibleLeafColumns().length;
  const rowsLength = isLoading ? 0 : tableData.getRowModel().rows.length;

  return (
    <Box sx={{ maxWidth: '100%', overflowX: 'auto', width: '100%' }}>
      <MuiTable sx={{ minWidth: 650, borderCollapse: 'collapse' }}>

        {/* Header */}
        <TableHead>
          {tableData.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableCell
                  colSpan={header.colSpan}
                  key={header.id}
                  sx={{
                    width: header.getSize(),
                    background: '#F1F5F9',
                    borderBottom: '2px solid #E2E8F0',
                    color: '#374151',
                    fontSize: '0.72rem',
                    fontWeight: 700,
                    letterSpacing: '0.6px',
                    padding: '13px 16px',
                    textTransform: 'uppercase',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {header.isPlaceholder
                    ? null
                    : flexRender(header.column.columnDef.header, header.getContext())}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableHead>

        {/* Body */}
        <TableBody>
          {isLoading && (
            <SkeletonTable
              cellCount={columnsLength}
              rowCount={tableData.getState().pagination.pageSize}
              skeletonHeight={25}
            />
          )}

          {!isLoading && rowsLength === 0 && (
            <TableRow>
              <TableCell align="center" colSpan={columnsLength} sx={{ border: 'none', py: 8 }}>
                <Box sx={{ alignItems: 'center', display: 'flex', flexDirection: 'column', gap: 1 }}>
                  <InboxOutlinedIcon sx={{ color: alpha('#0F1D4D', 0.18), fontSize: 44 }} />
                  <Typography sx={{ color: alpha('#0F1D4D', 0.35), fontSize: '0.875rem', fontWeight: 600 }}>
                    No records found
                  </Typography>
                </Box>
              </TableCell>
            </TableRow>
          )}

          {!isLoading &&
            tableData.getRowModel().rows.map((row, index) => (
              <TableRow
                key={row.id}
                onClick={() => onRowClick?.(row.original)}
                sx={{
                  cursor: onRowClick ? 'pointer' : 'default',
                  backgroundColor: index % 2 === 0 ? '#fff' : '#F8FAFC',
                  transition: 'background 0.15s',
                  '&:hover': {
                    backgroundColor: '#EFF6FF',
                    '& td': { color: '#0F1D4D' },
                  },
                  '& td': {
                    borderBottom: `1px solid ${alpha('#0F1D4D', 0.06)}`,
                  },
                  '&:last-child td': { borderBottom: 'none' },
                }}
              >
                {row.getVisibleCells().map((cell) => {
                  if (cell.column.id === 'select') {
                    return (
                      <TableCell
                        key={cell.id}
                        sx={{ padding: '10px 16px' }}
                      >
                        <Checkbox checked={cell.getValue() as boolean} size="small" />
                      </TableCell>
                    );
                  }

                  return (
                    <TableCell
                      key={cell.id}
                      sx={{
                        color: '#334155',
                        fontSize: '0.84rem',
                        fontWeight: 450,
                        padding: '11px 16px',
                      }}
                    >
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  );
                })}
              </TableRow>
            ))}
        </TableBody>
      </MuiTable>
    </Box>
  );
};

export default React.memo(ReactTable);
