import { useCallback, useMemo } from 'react';
import { useGetUserQuery } from '../../page/posApi';
import { IUserInfo } from '../Interface/user.interface';

/**
 * usePageQuery hook to set the url params and fetch from the url params
 * @returns
 */
const useUser = () => {
  const { data, isLoading, isError } = useGetUserQuery();

  // Use the top-level `data` object as the dependency — it's a stable reference
  // from RTK Query's cache and only changes when the server response changes.
  const userInfo = useMemo(
    () => (data?.data as IUserInfo) ?? null,
    [data]
  );

  const userHasRight = useCallback(
    (privilege: string) => {
      if (isLoading || isError || !userInfo) return false;
      return userInfo.privileges?.includes(privilege);
    },
    [userInfo, isError, isLoading]
  );

  const company = useMemo(
    () => (isLoading || isError || !userInfo ? {} : userInfo.company || {}),
    [userInfo, isError, isLoading]
  );

  const branch = useMemo(
    () => (isLoading || isError || !userInfo ? {} : userInfo.branch || {}),
    [userInfo, isError, isLoading]
  );

  return { userHasRight, company, branch };
};

export default useUser;
