import {
  Backdrop,
  Box,
  Button,
  CircularProgress,
  InputAdornment,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { Table } from '@tanstack/react-table';
import React, { useEffect, useRef, useState } from 'react';
import { useReactToPrint } from 'react-to-print';
import PosTablePagination from '../../components/Table/PosTablePagination';
import ReactTable from '../../components/Table/ReactTable';
import { ISalesReceipt } from '../../core/Interface/sale.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetSalesDetailsByOrderIdQuery } from '../posApi';
import AnimatedPage from '../../layouts/AnimatedPage';
import useOrderList from './useOrderList';
import SearchIcon from '@mui/icons-material/Search';
import ReceiptLongOutlinedIcon from '@mui/icons-material/ReceiptLongOutlined';
import { HEADER_GRADIENT } from '../../theme/appColors';

const NAVY = '#0F1D4D';

const OrderList = () => {
  const { table, isLoading, totalCount, invoiceId, setSearchText } =
    useOrderList();

  const {
    data: salesDetailsData,
    isLoading: salesDetailsLoading,
    isFetching,
  } = useGetSalesDetailsByOrderIdQuery(invoiceId.split('_')[0], {
    skip: !invoiceId,
  });

  const { setPage } = usePageQuery();
  const [salesDetails, setSalesDetails] = useState<ISalesReceipt>();
  const [localSearch, setLocalSearch] = useState('');
  const componentRef = useRef<HTMLDivElement | null>(null);

  const handlePrint = useReactToPrint({
    content: () => componentRef.current,
  });

  useEffect(() => {
    setSalesDetails(salesDetailsData?.data as ISalesReceipt);
  }, [salesDetailsData]);

  useEffect(() => {
    const printTimer = setTimeout(() => {
      if (salesDetails && componentRef.current) {
        handlePrint();
      }
    }, 10);

    return () => clearTimeout(printTimer);
  }, [salesDetails, handlePrint]);

  useEffect(() => {
    if (
      !isLoading &&
      table.getState().pagination.pageIndex !== 0 &&
      table.getRowModel().rows.length === 0
    ) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleSearch = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') setSearchText(localSearch);
  };

  return (
    <AnimatedPage>
      <Box data-testid="orderListDetails">

        {/* ── Header banner ───────────────────────────────────────── */}
        <Box
          sx={{
            alignItems: 'center',
            background: HEADER_GRADIENT,
            borderRadius: '12px',
            display: 'flex',
            flexWrap: 'wrap',
            gap: 1.5,
            mb: 2,
            px: { xs: 2, sm: 2.5 },
            py: { xs: 1.5, sm: 1.75 },
          }}
        >
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, flex: 1, minWidth: 0 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.14)',
                borderRadius: '8px',
                display: 'flex',
                flexShrink: 0,
                height: 34,
                justifyContent: 'center',
                width: 34,
              }}
            >
              <ReceiptLongOutlinedIcon sx={{ color: '#fff', fontSize: 18 }} />
            </Box>
            <Typography sx={{ color: '#fff', fontSize: { xs: 14, sm: 16 }, fontWeight: 700, lineHeight: 1.2 }}>
              Order List
            </Typography>
          </Box>

          {/* Search field + button — same height, grouped */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flex: { xs: 1, sm: 'none' }, minWidth: { xs: '100%', sm: 'auto' } }}>
            <TextField
              InputProps={{
                onKeyDown: handleSearch,
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon sx={{ color: 'rgba(255,255,255,0.55)', fontSize: 18 }} />
                  </InputAdornment>
                ),
              }}
              onChange={(e) => setLocalSearch(e.target.value)}
              placeholder="Order ID or customer name…"
              size="small"
              sx={{
                flex: 1,
                minWidth: { sm: 220, md: 280 },
                '& .MuiOutlinedInput-root': {
                  height: 40,
                  '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                  '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.7)' },
                  '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.45)' },
                  backgroundColor: 'rgba(255,255,255,0.12)',
                  borderRadius: '8px',
                },
                '& .MuiInputBase-input': {
                  color: '#fff',
                  '&::placeholder': { color: 'rgba(255,255,255,0.5)', opacity: 1 },
                },
              }}
              value={localSearch}
            />

            <Button
              onClick={() => setSearchText(localSearch)}
              sx={{
                background: 'rgba(255,255,255,0.18)',
                border: '1px solid rgba(255,255,255,0.3)',
                borderRadius: '8px',
                color: '#fff',
                flexShrink: 0,
                fontWeight: 600,
                height: 40,
                px: 2.5,
                textTransform: 'none',
                whiteSpace: 'nowrap',
                '&:hover': { background: 'rgba(255,255,255,0.28)', border: '1px solid rgba(255,255,255,0.5)' },
              }}
              variant="outlined"
            >
              Search
            </Button>
          </Box>
        </Box>

        <Backdrop
          open={salesDetailsLoading || isFetching}
          sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 1 }}
        >
          <CircularProgress color="inherit" />
        </Backdrop>

        <Box sx={{ overflow: 'auto', maxWidth: '100%', minHeight: 560 }}>
          <ReactTable
            isLoading={isLoading}
            {...(table as Table<object>)}
          />
        </Box>
        {table.getTotalSize() !== 0 && (
          <Box sx={{ borderTop: '1px solid #E3E5E5' }}>
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          </Box>
        )}
      </Box>
    </AnimatedPage>
  );
};

export default OrderList;
