import { Box, Chip, Grid, Typography } from '@mui/material';
import React from 'react';
import { appColors } from '../../../../theme/appColors';
import { useSelector } from 'react-redux';
import { selectBasketItems } from '../../store/SalesRichBasketSelector';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import BasketItemEditModel from './Model/BasketItemEditModel';
import { BasketItem } from '../../store/SalesRichBasketSlice';

export const profileLabel = (name: String, fontSize?: number) => (
  <Typography
    align="left"
    sx={{
      fontSize: fontSize ?? 13,
      fontWeight: 500,
      color: appColors.royalBlue[100],
      lineHeight: 1.2,
    }}
  >
    {name}
  </Typography>
);

export const profileValue = (val: String, fontSize?: number) => (
  <Typography
    align="right"
    sx={{
      fontSize: fontSize ?? 13,
      color: appColors.royalBlue[80],
      fontVariantNumeric: 'tabular-nums',
    }}
  >
    {val}
  </Typography>
);

const BasketItems = () => {
  const selectItem = useSelector(selectBasketItems);
  const [basketItemOpen, setBasketItemOpen] = React.useState(false);
  const [basketItem, setBasketItem] = React.useState<BasketItem>();

  if (selectItem.length === 0) {
    return (
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          opacity: 0.35,
          gap: 1,
          py: 4,
        }}
      >
        <Typography sx={{ fontSize: 13, color: appColors.royalBlue[60] }}>
          No items added yet
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: '4px 8px 0 8px' }}>
      {selectItem
        .slice()
        .reverse()
        .map((item, idx) => (
          <Grid
            alignItems="center"
            container
            key={item.id}
            onClick={() => {
              setBasketItem(item);
              setBasketItemOpen(true);
            }}
            spacing={1}
            sx={{
              py: '6px',
              px: '4px',
              cursor: 'pointer',
              borderBottom: `1px solid ${appColors.darkGray[10]}`,
              '&:last-child': { borderBottom: 'none' },
              flexWrap: 'nowrap',
              borderRadius: '6px',
              transition: 'background 0.15s ease',
              '&:hover': {
                backgroundColor: appColors.reflexBlue[10],
              },
            }}
          >
            <Grid
              item
              md={3}
              xs={3}
            >
              {profileLabel(item.name)}
            </Grid>
            <Grid
              item
              md={2}
              xs={2}
            >
              <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                <Chip
                  label={item.count}
                  size="small"
                  sx={{
                    height: 20,
                    fontSize: 11,
                    fontWeight: 700,
                    backgroundColor: appColors.reflexBlue[100],
                    color: appColors.white,
                    '& .MuiChip-label': { px: '6px' },
                  }}
                />
              </Box>
            </Grid>
            <Grid
              item
              md={3}
              xs={3}
            >
              {/* eslint-disable-next-line max-len */}
              {profileValue(getPriceFormatWithoutCurrency(item.unitPrice).toString())}
            </Grid>
            <Grid
              item
              md={3}
              xs={3}
            >
              {profileValue(
                `${getPriceFormatWithoutCurrency(item?.defaultDiscountAmount || 0)}${item.isDiscountPercentage ? '%' : ''}`
              )}
            </Grid>
            <Grid
              item
              md={3}
              xs={3}
            >
              {profileValue(
                (
                  (item.unitPrice -
                    (item.isDiscountPercentage
                      // eslint-disable-next-line max-len
                      ? (item.unitPrice / 100) * (item?.defaultDiscountAmount || 0)
                      : item?.defaultDiscountAmount || 0)) *
                  item.count
                ).toFixed(2)
              )}
            </Grid>
          </Grid>
        ))}
      {basketItemOpen && (
        <BasketItemEditModel
          handleClose={() => setBasketItemOpen(false)}
          item={basketItem}
          open={basketItemOpen}
        />
      )}
    </Box>
  );
};

export default React.memo(BasketItems);
