import {
  Box,
  Button,
  Checkbox,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  FormControlLabel,
  IconButton,
  InputAdornment,
  Slide,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import { TransitionProps } from '@mui/material/transitions';
import { appColors } from '../../../../../theme/appColors';
import {
  BasketItem,
  removeBasketItem,
  updateBasketItem,
} from '../../../store/SalesRichBasketSlice';
import { useAppDispatch } from '../../../../../store/hooks';
import { useFormik } from 'formik';
import { IAddCount } from '../../../../../core/Interface/property.interface';
import { useVoidItemFromBasketMutation } from '../../../../posApi';
import { useNotifier } from '../../../../../core/Notifier';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import RemoveCircleOutlineIcon from '@mui/icons-material/RemoveCircleOutline';
import LocalOfferOutlinedIcon from '@mui/icons-material/LocalOfferOutlined';
import PriceChangeOutlinedIcon from '@mui/icons-material/PriceChangeOutlined';

// eslint-disable-next-line @typescript-eslint/no-shadow
interface IBasketItemEditModel {
  item?: BasketItem;
  open: boolean;
  handleClose: () => void;
}

const inputFieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(appColors.white, 0.92),
    borderRadius: '4px',
    '& fieldset': {
      borderColor: alpha(appColors.blueGreyishLight[80], 0.16),
    },
    '&:hover fieldset': {
      borderColor: alpha('#2563EB', 0.28),
    },
    '&.Mui-focused': {
      boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.10)}`,
    },
    '&.Mui-focused fieldset': {
      borderColor: '#2563EB',
    },
  },
};

const labelSx = {
  color: '#142352',
  fontSize: '0.86rem',
  fontWeight: 700,
  mb: 0.8,
};

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & {
    children: React.ReactElement<string, string>;
  },
  ref: React.Ref<unknown>
) {
  return (
    <Slide
      direction="up"
      ref={ref}
      {...props}
    />
  );
});

// eslint-disable-next-line react/no-multi-comp
const BasketItemEditModel: React.FC<IBasketItemEditModel> = ({
  item,
  open,
  handleClose,
}) => {
  const dispatch = useAppDispatch();
  const [voidItemFromBasket, { isLoading }] =
    useVoidItemFromBasketMutation();
  const { showErrorMessage, showMessage } = useNotifier();

  const voidBasketItem = async () => {
    try {
      const voidItem = await voidItemFromBasket({
        productId: item?.id || '',
        qty: item?.count || 0,
      }).unwrap();
      if (!voidItem.status) {
        showErrorMessage(voidItem.message);
      } else {
        showMessage(voidItem.message);
        dispatch(removeBasketItem(item?.id || ''));
        handleClose();
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      count: item?.count,
      discount: item?.defaultDiscountAmount ?? 0,
      discountAsPercentage: item?.isDiscountPercentage ?? false,
      givenPrice:
        item?.unitPrice && item?.defaultDiscountAmount
          ? Math.max(
              item.unitPrice - (
                item.isDiscountPercentage
                  ? (item.unitPrice * item.defaultDiscountAmount) / 100
                  : item.defaultDiscountAmount
              ),
              0
            )
          : 0,
      isGivenPrice: false,
    },
    onSubmit: async (values) => {
      let discountValue = values.discount || 0;
      if (values.isGivenPrice && item?.unitPrice) {
        // Convert "given price" to a fixed discount amount; mark as non-percentage
        discountValue = Math.max(item.unitPrice - values.givenPrice, 0);
      }
      // For percentage mode: keep discountValue as the raw percentage number.
      // getDiscountSum applies "(unitPrice * pct / 100) * qty" using the flag.
      // Do NOT pre-convert here — that would cause a double-conversion in getDiscountSum.
      if (discountValue >= 0 && item) {
        const itemCount: IAddCount = {
          code: item.code || '',
          count: values.count || 1,
          discountValue: discountValue,
          id: item.id || '',
          isDiscountPercentage: !values.isGivenPrice && (values.discountAsPercentage || false),
          isGivingPrice: values.isGivenPrice,
        };
        dispatch(updateBasketItem(itemCount));
      }
      handleClose();
    },
    validate: (values) => {
      const errors: Partial<Record<string, string>> = {};
      const maxFlat = item?.maxDiscountAmount ?? 0;
      if (!maxFlat) return errors;

      const up = item?.unitPrice ?? 0;
      let effectiveFlat: number;

      if (values.isGivenPrice) {
        effectiveFlat = Math.max(up - (values.givenPrice ?? 0), 0);
      } else if (values.discountAsPercentage) {
        effectiveFlat = ((values.discount ?? 0) / 100) * up;
      } else {
        effectiveFlat = values.discount ?? 0;
      }

      if (effectiveFlat > maxFlat) {
        if (values.isGivenPrice) {
          const minPrice = Math.max(0, up - maxFlat);
          errors.givenPrice = `Min selling price is ${minPrice.toFixed(2)} (max discount: ${maxFlat.toFixed(2)})`;
        } else if (values.discountAsPercentage) {
          const maxPct = up > 0 ? (maxFlat / up) * 100 : 0;
          errors.discount = `Max ${maxPct.toFixed(1)}% (= ${maxFlat.toFixed(2)})`;
        } else {
          errors.discount = `Max discount is ${maxFlat.toFixed(2)}`;
        }
      }

      return errors;
    },
  });

  const unitPrice = item?.unitPrice ?? 0;
  const count = formik.values.count ?? 1;
  const discount = formik.values.discount ?? 0;
  const givenPrice = formik.values.givenPrice ?? 0;

  const effectiveUnitPrice = (() => {
    if (formik.values.isGivenPrice) return givenPrice;
    if (formik.values.discountAsPercentage)
      return Math.max(unitPrice - (unitPrice * discount) / 100, 0);
    return Math.max(unitPrice - discount, 0);
  })();

  const lineTotal = effectiveUnitPrice * count;
  const discountActive = !formik.values.isGivenPrice;
  const givenPriceActive = formik.values.isGivenPrice;

  const modeCardSx = (active: boolean) => ({
    alignItems: 'center',
    background: active
      ? alpha('#2563EB', 0.07)
      : alpha(appColors.blueGreyishLight[80], 0.04),
    border: `2px solid ${
      active
        ? alpha('#2563EB', 0.40)
        : alpha(appColors.blueGreyishLight[80], 0.16)
    }`,
    borderRadius: '6px',
    cursor: 'pointer',
    display: 'flex',
    flex: 1,
    gap: 1,
    px: 2,
    py: 1.5,
  });

  return (
    <Dialog
      PaperProps={{
        component: 'form',
        noValidate: true,
        onSubmit: formik.handleSubmit,
        sx: {
          background:
            'linear-gradient(180deg, rgba(255,255,255,0.98) 0%,'
            + ' rgba(248,251,255,0.96) 100%)',
          border: `1px solid ${alpha(
            appColors.blueGreyishLight[80], 0.1
          )}`,
          borderRadius: '8px',
          boxShadow: '0 30px 80px rgba(15,23,42,0.28)',
          maxWidth: 'calc(100vw - 32px)',
          overflow: 'hidden',
          width: 520,
        },
      }}
      TransitionComponent={Transition}
      fullWidth
      maxWidth={false}
      onClose={handleClose}
      open={open}
    >
      {/* ── Header ── */}
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background:
              'linear-gradient(135deg,'
              + ' rgba(239,246,255,0.96) 0%,'
              + ' rgba(224,236,255,0.98) 54%,'
              + ' rgba(255,247,237,0.96) 100%)',
            borderBottom: `1px solid ${alpha(
              appColors.blueGreyishLight[80], 0.1
            )}`,
            px: { xs: 2.5, md: 4 },
            py: { xs: 2.5, md: 3 },
          }}
        >
          <Box
            sx={{
              alignItems: 'flex-start',
              display: 'flex',
              gap: 2,
              justifyContent: 'space-between',
            }}
          >
            <Box sx={{ minWidth: 0 }}>
              <Typography
                sx={{
                  color: alpha(appColors.blueGreyishLight[80], 0.62),
                  fontSize: '0.74rem',
                  letterSpacing: '0.16em',
                  mb: 0.9,
                  textTransform: 'uppercase',
                }}
              >
                Basket Item
              </Typography>
              <Typography
                sx={{
                  color: '#142352',
                  fontSize: { xs: '1.2rem', md: '1.5rem' },
                  fontWeight: 700,
                  lineHeight: 1.2,
                  maxWidth: 360,
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
              >
                {item?.name}
              </Typography>
              {item?.code && (
                <Typography
                  sx={{
                    color: alpha(appColors.blueGreyishLight[80], 0.7),
                    fontSize: '0.84rem',
                    mt: 0.5,
                  }}
                >
                  Code: {item.code}
                </Typography>
              )}
            </Box>
            <IconButton
              onClick={handleClose}
              sx={{
                backgroundColor: alpha(appColors.white, 0.72),
                border: `1px solid ${alpha(
                  appColors.blueGreyishLight[80], 0.1
                )}`,
                color: alpha(appColors.blueGreyishLight[80], 0.72),
                mr: -0.8,
                mt: -0.5,
                '&:hover': {
                  backgroundColor: alpha(appColors.white, 0.94),
                },
              }}
            >
              <CloseRoundedIcon />
            </IconButton>
          </Box>
        </Box>
      </DialogTitle>

      {/* ── Content ── */}
      <DialogContent sx={{ p: 0 }}>
        <Box
          sx={{
            background:
              'radial-gradient(circle at top right,'
              + ' rgba(37,99,235,0.04), transparent 28%),'
              + ' linear-gradient(180deg,'
              + ' rgba(255,255,255,0.92) 0%,'
              + ' rgba(248,251,255,0.88) 100%)',
            px: { xs: 2.5, md: 4 },
            py: { xs: 2.5, md: 3 },
          }}
        >
          {/* Info strip */}
          <Box
            sx={{
              alignItems: 'center',
              background: alpha('#2563EB', 0.04),
              border: `1px solid ${alpha('#2563EB', 0.12)}`,
              borderRadius: '6px',
              display: 'flex',
              gap: 4,
              mb: 3,
              px: 2.5,
              py: 1.5,
            }}
          >
            <Box>
              <Typography
                sx={{
                  color: alpha(appColors.blueGreyishLight[80], 0.72),
                  fontSize: 10,
                  fontWeight: 600,
                  letterSpacing: '1px',
                  textTransform: 'uppercase',
                }}
              >
                Unit Price
              </Typography>
              <Typography
                sx={{
                  color: '#142352',
                  fontSize: 15,
                  fontWeight: 700,
                }}
              >
                {unitPrice.toFixed(2)}
              </Typography>
            </Box>
            <Divider
              flexItem
              orientation="vertical"
            />
            <Box>
              <Typography
                sx={{
                  color: alpha(appColors.blueGreyishLight[80], 0.72),
                  fontSize: 10,
                  fontWeight: 600,
                  letterSpacing: '1px',
                  textTransform: 'uppercase',
                }}
              >
                Current Qty
              </Typography>
              <Typography
                sx={{
                  color: '#142352',
                  fontSize: 15,
                  fontWeight: 700,
                }}
              >
                {item?.count ?? 0}
              </Typography>
            </Box>
            {(item?.maxDiscountAmount ?? 0) > 0 && (
              <>
                <Divider
                  flexItem
                  orientation="vertical"
                />
                <Box>
                  <Typography
                    sx={{
                      color: alpha('#B45309', 0.8),
                      fontSize: 10,
                      fontWeight: 600,
                      letterSpacing: '1px',
                      textTransform: 'uppercase',
                    }}
                  >
                    Max Discount
                  </Typography>
                  <Typography
                    sx={{
                      color: '#92400e',
                      fontSize: 15,
                      fontWeight: 700,
                    }}
                  >
                    {item!.maxDiscountAmount.toFixed(2)}
                  </Typography>
                </Box>
              </>
            )}
          </Box>

          {/* Quantity */}
          <Box sx={{ mb: 3 }}>
            <Typography sx={labelSx}>Quantity</Typography>
            <Stack
              alignItems="center"
              direction="row"
              spacing={1}
            >
              <IconButton
                onClick={() =>
                  formik.setFieldValue(
                    'count',
                    Math.max((formik.values.count ?? 1) - 1, 1)
                  )
                }
                size="small"
                sx={{
                  border: `1.5px solid ${alpha('#2563EB', 0.24)}`,
                  borderRadius: '4px',
                  color: '#2563EB',
                  p: 0.5,
                  '&:hover': {
                    background: alpha('#2563EB', 0.06),
                  },
                }}
              >
                <RemoveCircleOutlineIcon fontSize="small" />
              </IconButton>
              <TextField
                autoComplete="off"
                inputProps={{
                  min: 1,
                  step: 'any',
                  style: {
                    fontWeight: 700,
                    fontSize: 16,
                    textAlign: 'center',
                  },
                }}
                size="small"
                sx={{ width: 100, ...inputFieldSx }}
                type="number"
                {...formik.getFieldProps('count')}
              />
              <IconButton
                onClick={() =>
                  formik.setFieldValue(
                    'count',
                    (formik.values.count ?? 1) + 1
                  )
                }
                size="small"
                sx={{
                  border: `1.5px solid ${alpha('#2563EB', 0.24)}`,
                  borderRadius: '4px',
                  color: '#2563EB',
                  p: 0.5,
                  '&:hover': {
                    background: alpha('#2563EB', 0.06),
                  },
                }}
              >
                <AddCircleOutlineIcon fontSize="small" />
              </IconButton>
            </Stack>
          </Box>

          <Divider sx={{ mb: 3 }} />

          {/* Pricing mode */}
          <Box sx={{ mb: 3 }}>
            <Typography sx={labelSx}>Pricing Mode</Typography>
            <Stack
              direction="row"
              spacing={1.5}
            >
              <Box
                onClick={() => {
                  formik.setFieldValue('isGivenPrice', false);
                  formik.setFieldValue('discount', 0, false);
                }}
                sx={modeCardSx(discountActive)}
              >
                <LocalOfferOutlinedIcon
                  sx={{
                    color: discountActive
                      ? '#2563EB'
                      : alpha(appColors.blueGreyishLight[80], 0.72),
                    fontSize: 18,
                  }}
                />
                <Box>
                  <Typography
                    sx={{
                      color: discountActive
                        ? '#142352'
                        : alpha(appColors.blueGreyishLight[80], 0.8),
                      fontSize: '0.82rem',
                      fontWeight: 700,
                    }}
                  >
                    Apply Discount
                  </Typography>
                  <Typography
                    sx={{
                      color: alpha(appColors.blueGreyishLight[80], 0.7),
                      fontSize: '0.74rem',
                    }}
                  >
                    Deduct from unit price
                  </Typography>
                </Box>
              </Box>

              <Box
                onClick={() => {
                  formik.setFieldValue('isGivenPrice', true);
                  formik.setFieldValue('discount', 0, false);
                  formik.setFieldValue(
                    'discountAsPercentage',
                    false,
                    false
                  );
                }}
                sx={modeCardSx(givenPriceActive)}
              >
                <PriceChangeOutlinedIcon
                  sx={{
                    color: givenPriceActive
                      ? '#2563EB'
                      : alpha(appColors.blueGreyishLight[80], 0.72),
                    fontSize: 18,
                  }}
                />
                <Box>
                  <Typography
                    sx={{
                      color: givenPriceActive
                        ? '#142352'
                        : alpha(appColors.blueGreyishLight[80], 0.8),
                      fontSize: '0.82rem',
                      fontWeight: 700,
                    }}
                  >
                    Set Selling Price
                  </Typography>
                  <Typography
                    sx={{
                      color: alpha(appColors.blueGreyishLight[80], 0.7),
                      fontSize: '0.74rem',
                    }}
                  >
                    Override with exact price
                  </Typography>
                </Box>
              </Box>
            </Stack>
          </Box>

          {/* Discount field */}
          {!formik.values.isGivenPrice && (
            <Box sx={{ mb: 3 }}>
              <Typography sx={labelSx}>Discount</Typography>
              <Stack
                alignItems="center"
                direction="row"
                spacing={2}
              >
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={formik.values.discountAsPercentage}
                      name="discountAsPercentage"
                      onChange={() => {
                        formik.setFieldValue(
                          'discountAsPercentage',
                          !formik.values.discountAsPercentage
                        );
                        formik.setFieldValue('discount', 0, false);
                      }}
                      size="small"
                      sx={{ p: 0.5 }}
                    />
                  }
                  label={
                    <Typography
                      sx={{
                        color: '#142352',
                        fontSize: '0.82rem',
                        fontWeight: 600,
                      }}
                    >
                      Percentage (%)
                    </Typography>
                  }
                  sx={{ m: 0 }}
                />
                <TextField
                  InputProps={{
                    endAdornment: formik.values.discountAsPercentage
                      ? (
                        <InputAdornment position="end">
                          <Typography
                            sx={{
                              color: alpha(
                                appColors.blueGreyishLight[80],
                                0.72
                              ),
                              fontSize: 13,
                              fontWeight: 600,
                            }}
                          >
                            %
                          </Typography>
                        </InputAdornment>
                      )
                      : undefined,
                    inputProps: {
                      min: 0,
                      ...(item?.maxDiscountAmount && {
                        max: formik.values.discountAsPercentage && unitPrice > 0
                          ? (item.maxDiscountAmount / unitPrice) * 100
                          : item.maxDiscountAmount,
                      }),
                    },
                  }}
                  autoComplete="off"
                  error={!!formik.errors.discount}
                  helperText={formik.errors.discount}
                  placeholder="0.00"
                  size="small"
                  sx={{ flex: 1, ...inputFieldSx }}
                  type="number"
                  inputProps={{ step: 'any' }}
                  {...formik.getFieldProps('discount')}
                />
              </Stack>
            </Box>
          )}

          {/* Selling price field */}
          {formik.values.isGivenPrice && (
            <Box sx={{ mb: 3 }}>
              <Typography sx={labelSx}>Selling Price</Typography>
              <TextField
                InputProps={{
                  inputProps: {
                    max: unitPrice,
                    min: item?.maxDiscountAmount
                      ? Math.max(0, unitPrice - item.maxDiscountAmount)
                      : 0,
                  },
                }}
                autoComplete="off"
                error={!!formik.errors.givenPrice}
                helperText={formik.errors.givenPrice}
                placeholder="0.00"
                size="small"
                sx={{ width: '100%', ...inputFieldSx }}
                type="number"
                inputProps={{ step: 'any' }}
                {...formik.getFieldProps('givenPrice')}
              />
            </Box>
          )}

          {/* Live price summary */}
          <Box
            sx={{
              alignItems: 'center',
              background: alpha('#059669', 0.06),
              border: `1px solid ${alpha('#059669', 0.18)}`,
              borderRadius: '6px',
              display: 'flex',
              justifyContent: 'space-between',
              px: 2.5,
              py: 1.5,
            }}
          >
            <Box>
              <Typography
                sx={{
                  color: alpha('#059669', 0.8),
                  fontSize: '0.7rem',
                  fontWeight: 600,
                  letterSpacing: '1px',
                  textTransform: 'uppercase',
                }}
              >
                Effective Unit Price
              </Typography>
              <Typography
                sx={{
                  color: '#065f46',
                  fontSize: '1rem',
                  fontWeight: 700,
                }}
              >
                {effectiveUnitPrice.toFixed(2)}
              </Typography>
            </Box>
            <Box sx={{ textAlign: 'right' }}>
              <Typography
                sx={{
                  color: alpha('#059669', 0.8),
                  fontSize: '0.7rem',
                  fontWeight: 600,
                  letterSpacing: '1px',
                  textTransform: 'uppercase',
                }}
              >
                Line Total × {count}
              </Typography>
              <Typography
                sx={{
                  color: '#065f46',
                  fontSize: '1.3rem',
                  fontWeight: 800,
                }}
              >
                {lineTotal.toFixed(2)}
              </Typography>
            </Box>
          </Box>
        </Box>
      </DialogContent>

      {/* ── Footer ── */}
      <DialogActions sx={{ p: 0 }}>
        <Box
          sx={{
            alignItems: { xs: 'stretch', md: 'center' },
            backgroundColor: alpha('#F8FAFC', 0.94),
            borderTop: `1px solid ${alpha(
              appColors.blueGreyishLight[80], 0.08
            )}`,
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            px: { xs: 2.5, md: 4 },
            py: 2.3,
            width: '100%',
          }}
        >
          <Button
            disabled={isLoading}
            onClick={voidBasketItem}
            startIcon={
              isLoading
                ? (
                  <CircularProgress
                    size={14}
                    sx={{ color: 'inherit' }}
                  />
                )
                : <DeleteOutlineIcon fontSize="small" />
            }
            sx={{
              borderColor: alpha('#B42318', 0.4),
              borderRadius: '4px',
              color: '#B42318',
              fontWeight: 700,
              height: 46,
              px: 2.5,
              textTransform: 'none',
            }}
            variant="outlined"
          >
            Remove
          </Button>

          <Box
            sx={{
              display: 'flex',
              flexDirection: { xs: 'column-reverse', sm: 'row' },
              gap: 1.5,
              width: { xs: '100%', md: 'auto' },
            }}
          >
            <Button
              disabled={isLoading}
              onClick={handleClose}
              sx={{
                borderColor: alpha('#142352', 0.22),
                borderRadius: '4px',
                color: '#142352',
                fontWeight: 700,
                height: 46,
                minWidth: 120,
                px: 3,
                textTransform: 'none',
              }}
              variant="outlined"
            >
              Cancel
            </Button>
            <Button
              autoFocus
              disabled={isLoading || Object.keys(formik.errors).length > 0}
              sx={{
                background:
                  'linear-gradient(135deg, #2563EB 0%, #1D4ED8 100%)',
                borderRadius: '4px',
                boxShadow: '0 12px 24px rgba(37,99,235,0.22)',
                fontWeight: 700,
                height: 46,
                minWidth: 150,
                px: 3,
                textTransform: 'none',
                '&:hover': {
                  background:
                    'linear-gradient(135deg, #1D4ED8 0%, #1E40AF 100%)',
                },
                '&.Mui-disabled': {
                  background: '#cbd5e1',
                  boxShadow: 'none',
                  color: '#64748b',
                },
              }}
              type="submit"
              variant="contained"
            >
              Update Item
            </Button>
          </Box>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(BasketItemEditModel);
