import {
  Box,
  TablePagination,
  TablePaginationBaseProps,
  Typography,
} from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';

/**
 * @input MuiTablePaginationProps => for this you can refer MUI TablePagination documentation
 */
interface TablePaginationProps extends TablePaginationBaseProps {
  count: number;
  page: number;
  onPageChange: (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => void;
  onRowsPerPageChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  rowsPerPage: number;
  // If you provide empty array you can get 'Row per page:' with out row per page option
  rowsPerPageOptions:
    | (
        | number
        | {
            value: number;
            label: string;
          }
      )[]
    | undefined;
}

const PosTablePagination = ({ ...rest }: TablePaginationProps) => {
  const { t } = useTranslation(['common']);
  return (
    <Box
      alignItems="center"
      display="flex"
      justifyContent="flex-end"
      sx={{
        borderTop: '1px solid #E2E8F0',
        backgroundColor: '#F8FAFC',
      }}
    >
      {rest.rowsPerPageOptions?.length === 0 && (
        <Box
          alignItems="center"
          display="flex"
          mr={2}
        >
          <Typography sx={{ pr: 0.5, fontSize: '14px' }}>
            {t('common:rowPerPage')}
          </Typography>
          <Typography sx={{ fontSize: '14px' }}>{rest.rowsPerPage}</Typography>
        </Box>
      )}

      <TablePagination
        component="div"
        {...rest}
        sx={{
          '& .MuiTablePagination-toolbar': {
            minHeight: 40,
            paddingLeft: 2,
            paddingRight: 2,
          },
          '& .MuiTablePagination-selectLabel': {
            fontSize: '14px',
          },
          '& .MuiTablePagination-displayedRows': {
            fontSize: '14px',
          },
          '& .MuiTablePagination-actions button': {
            borderRadius: 2,
          },
        }}
      />
    </Box>
  );
};

export default React.memo(PosTablePagination);
